import axios from "axios";

const cache = {};

// ✅ AUTO BASE URL SWITCH (LOCAL + PHONE)
const baseURL =
  window.location.hostname === "localhost"
    ? "http://127.0.0.1:8000"
    : process.env.REACT_APP_API_URL || "https://k3kfpzfc-8001.inc1.devtunnels.ms";

const api = axios.create({
  baseURL,
  timeout: 8000, // थोड़ा बढ़ाया for tunnel delay
  headers: {
    "Content-Type": "application/json",
  },
});

// 🔑 Cache Key Generator
const getCacheKey = (url, config = {}) => {
  const params = config.params ? JSON.stringify(config.params) : "";
  return `${url}?${params}`;
};

// 🔐 REQUEST INTERCEPTOR (TOKEN)
api.interceptors.request.use((config) => {
  const token = localStorage.getItem("token");

  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }

  return config;
});

// 📦 RESPONSE INTERCEPTOR
api.interceptors.response.use(
  (response) => {
    const method = response.config?.method?.toLowerCase();
    const url = response.config?.url;

    // ✅ Cache only GET
    if (method === "get" && url) {
      const key = getCacheKey(url, response.config);
      cache[key] = {
        data: response.data,
        time: Date.now(),
      };
    }

    // ❌ Clear cache on write operations
    if (["post", "put", "delete", "patch"].includes(method)) {
      Object.keys(cache).forEach((key) => delete cache[key]);
    }

    return response;
  },

  async (error) => {
    const config = error.config;

    // ❌ Avoid retry loop
    if (!config || config.__retry) {
      return Promise.reject(error);
    }

    // 🔁 Retry only for network errors
    if (!error.response) {
      config.__retry = true;
      return api(config);
    }

    return Promise.reject(error);
  }
);

// 💾 OVERRIDE GET (WITH CACHE + EXPIRY)
const axiosGet = api.get.bind(api);

api.get = async (url, config = {}) => {
  const cacheKey = getCacheKey(url, config);
  const cached = cache[cacheKey];

  // ✅ Cache expiry (5 sec)
  const CACHE_TIME = 5000;

  if (
    config.cache !== false &&
    cached &&
    Date.now() - cached.time < CACHE_TIME
  ) {
    return {
      data: cached.data,
      status: 200,
      statusText: "OK",
      headers: {},
      config,
    };
  }

  const response = await axiosGet(url, config);

  // ✅ Save fresh cache
  cache[cacheKey] = {
    data: response.data,
    time: Date.now(),
  };

  return response;
};

// 🧹 CLEAR CACHE
api.clearCache = (keys = []) => {
  if (!keys.length) {
    Object.keys(cache).forEach((key) => delete cache[key]);
    return;
  }

  keys.forEach((key) => {
    Object.keys(cache)
      .filter((cacheKey) => cacheKey.startsWith(key))
      .forEach((cacheKey) => delete cache[cacheKey]);
  });
};

export default api;
